import {describe,it,expect} from "vitest";
import {createPublicKey,verify} from "node:crypto";
import {canonicalGpt02NativeRecoveryFenceProof} from
  "../gpt02NativeRecoveryFenceProofContract.js";

// Generated by the independent Python cryptography Ed25519 implementation
// with test-only private seed bytes(range(32)). NEVER provision as a real key.
const PYTHON_VECTOR_PUBLIC="03a107bff3ce10be1d70dd18e74bc09967e4d6309ba50d5f1ddc8664125531b8";
const PYTHON_VECTOR_SIGNATURE="77f26f1ddea809558f665b54a8341eacc1294a6250a367868d0718839ff060955093bd21c86db413e8fb1bf1400e5961e0317b3c71a55feb1e853e4dbfa9800c";
const proof={
  protocol:"ai-core-gpt02-recovery-fence/v1",
  reservationId:"22aa961d-ac1e-4e12-a2c8-28ed07ff97cc",
  parentCommandId:"83db99f5-cbda-4e60-be71-3090fb411bbb",
  childCommandId:"41aa961d-ac1e-4e12-a2c8-28ed07ff97cc",
  humanReviewId:6,jobId:135,workerId:"gpt02-dell-worker",
  artifactSha256:"f".repeat(64),fencingToken:1,sequence:0,
  issuedAtUtcMs:1700000000000,expiresAtUtcMs:1700000030000,
};
const pub=createPublicKey({
  key:Buffer.concat([
    Buffer.from("302a300506032b6570032100","hex"),
    Buffer.from(PYTHON_VECTOR_PUBLIC,"hex"),
  ]),
  format:"der",type:"spki",
});
describe("Node/Python DEV native fence interoperability (NO signing authority)",()=>{
  it("matches Python canonical byte vector and validates its Ed25519 signature",()=>{
    const data=canonicalGpt02NativeRecoveryFenceProof(proof);
    expect(data.toString("utf8")).toBe(
      "ai-core-gpt02-recovery-fence/v1\n"+
      JSON.stringify(Object.fromEntries(Object.entries(proof).sort(([a],[b])=>a<b?-1:a>b?1:0))));
    expect(verify(null,data,pub,Buffer.from(PYTHON_VECTOR_SIGNATURE,"hex"))).toBe(true);
  });
  it.each([
    {childCommandId:proof.parentCommandId},
    {fencingToken:2},
    {sequence:1},
    {workerId:"another"},
    {artifactSha256:"e".repeat(64)},
    {expiresAtUtcMs:1700000030001},
  ])("same signature cannot be used for modified field %j",(override)=>{
    const data=canonicalGpt02NativeRecoveryFenceProof({...proof,...override});
    expect(verify(null,data,pub,Buffer.from(PYTHON_VECTOR_SIGNATURE,"hex"))).toBe(false);
  });
  it.each([
    {...proof,fencingToken:0},
    {...proof,fencingToken:Number.MAX_SAFE_INTEGER+1},
    {...proof,sequence:-1},
    {...proof,humanReviewId:true},
    {...proof,jobId:1.2},
    {...proof,childCommandId:"BAD"},
    {...proof,workerId:"dell\nworker"},
    {...proof,artifactSha256:"bad"},
    {...proof,expiresAtUtcMs:proof.issuedAtUtcMs},
    {...proof,expiresAtUtcMs:proof.issuedAtUtcMs+120001},
    {...proof,unexpected:"allow"},
    {protocol:proof.protocol},
    null,
  ])("refuses unsafe server proof before any key use: %j",(value)=>{
    expect(()=>canonicalGpt02NativeRecoveryFenceProof(value)).toThrow();
  });
});
